import ast
import requests
from bs4 import BeautifulSoup
def task_func(url):
    """
    Fetches the content of a webpage specified by its URL, parses it to find <script> tags,
    and attempts to evaluate any string within these tags as a Python dictionary.

    If an error occurs during the request or if no dictionaries are found/evaluable,
    an empty list is returned.

    Parameters:
    - url (str): The URL of the webpage to process.

    Returns:
    - list of dict: A list containing dictionaries that were successfully evaluated from
      string representations within <script> tags on the webpage.
    """
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
    except Exception:
        return []

    soup = BeautifulSoup(response.content, 'html.parser')
    script_tags = soup.find_all('script')
    dictionaries = []

    for script in script_tags:
        script_content = script.string
        if script_content is None:
            continue
        # Try to find dictionary-like substrings
        lines = script_content.split('\n')
        for line in lines:
            line = line.strip()
            # Look for lines that might contain a Python dictionary
            if line.startswith('{') and line.endswith('}'):
                try:
                    # Use ast.literal_eval for safe evaluation
                    result = ast.literal_eval(line)
                    if isinstance(result, dict):
                        dictionaries.append(result)
                except (SyntaxError, ValueError):
                    continue
            # Also try to find variable assignments that might be dictionaries
            # e.g., var data = {...};
            if '=' in line:
                parts = line.split('=', 1)
                if len(parts) == 2:
                    value_part = parts[1].rstrip(';').strip()
                    if value_part.startswith('{') and value_part.endswith('}'):
                        try:
                            result = ast.literal_eval(value_part)
                            if isinstance(result, dict):
                                dictionaries.append(result)
                        except (SyntaxError, ValueError):
                            continue

    return dictionaries

